input.value:
timeseries {
  successful = max(custom.exchange.submission.successful.persec),
  tempFailures = max(custom.exchange.submission.temp_failures.persec),
  failed = max(custom.exchange.submission.failed.persec),
  pending = max(custom.exchange.is.messages_queued_for_submission)
}, by: {exchange.server}, from: now() - 1h, interval: 1m

timeseries {
  running = min(custom.exchange.service.running, scalar: true),
  present = max(custom.exchange.service.present, scalar: true)
}, by: {exchange.server, service, label}, from: now() - 15m
| filter present == 1 and running == 0
| sort server asc, service asc

timeseries {
  hybridMessages = max(custom.exchange.hybrid.outbound.message_count, scalar: true),
  hybridRetry = max(custom.exchange.hybrid.outbound.retry_messages, scalar: true)
}, by: {exchange.server, exchange.environment, mail_path}, from: now() - 15m

timeseries {
  copyQueue = max(custom.exchange.database.copy_queue_length, scalar: true),
  mounted = max(custom.exchange.database.mounted, scalar: true)
}, by: {exchange.server, exchange.environment, database.copy, database.name, database.status}, from: now() - 15m
| sort database.name asc
